package it.pagopa.posgw.common.domain.v1

import it.pagopa.posgw.common.annotation.ValueObject
import it.pagopa.posgw.common.domain.v1.sessions.Session
import java.util.UUID

/**
 * Identifies a payment session.
 *
 * @param id UUID identifying the session; a random UUID is generated by default.
 */
@ValueObject @JvmInline value class SessionId(val id: UUID = UUID.randomUUID()){
    companion object{
        fun of(uuid: String): SessionId = SessionId(UUID.fromString(uuid))
    }
}
